/**
 * Documents provided by the human: upload of every format, text extraction,
 * dedup, prompt injection at start and mid-run announcement, deletion.
 * Needs the mock LLM + a server configured by e2e-mock.ts, and the samples
 * generated by scripts/make-doc-samples.py:
 *   python scripts/make-doc-samples.py data-test-samples
 *   API=http://127.0.0.1:4399/api SAMPLES=data-test-samples npx tsx scripts/e2e-documents.ts
 */
import fs from 'node:fs'
import path from 'node:path'

const API = process.env.API ?? 'http://127.0.0.1:4399/api'
const SAMPLES = path.resolve(process.env.SAMPLES ?? 'data-test-samples')

async function call<T = any>(method: string, p: string, body?: unknown): Promise<T> {
  const r = await fetch(`${API}${p}`, { method, headers: body ? { 'content-type': 'application/json' } : {}, body: body ? JSON.stringify(body) : undefined })
  const j = await r.json()
  if (!r.ok) throw new Error(`${method} ${p} → ${r.status} ${JSON.stringify(j)}`)
  return j as T
}
const assert = (cond: unknown, msg: string): void => {
  console.log(`${cond ? '✔' : '✘'} ${msg}`)
  if (!cond) process.exitCode = 1
}
const wait = (ms: number): Promise<void> => new Promise(r => setTimeout(r, ms))

async function upload(projectId: string, files: string[]): Promise<{ status: number; body: any }> {
  const fd = new FormData()
  for (const f of files) fd.append('file', new Blob([fs.readFileSync(path.join(SAMPLES, f))]), path.basename(f))
  const r = await fetch(`${API}/projects/${projectId}/documents`, { method: 'POST', body: fd })
  return { status: r.status, body: await r.json() }
}

const text = async (projectId: string, sid: string): Promise<string> => (await call<{ text: string }>('GET', `/projects/${projectId}/sources/${sid}/text`)).text

const project = await call('POST', '/projects', { title: 'Docs', question: 'TEST_DOCS Quel est le seuil du code de surface ?', config: { permission: 'auto', supervisorEvery: 0 } })
const id = project.id as string

const singles = ['note.docx', 'slides.pptx', 'mesures.xlsx', 'rapport.odt', 'livre.epub', 'notes.md', 'data.csv', 'page.html', 'calc.ipynb', 'latin1.txt', 'figure.png', 'article.pdf']
const got: Record<string, any> = {}
for (const f of singles) {
  const r = await upload(id, [f])
  const doc = r.body.documents?.[0]
  got[f] = doc
  if (!doc) console.log(`  ${f} →`, JSON.stringify(r.body).slice(0, 300))
}
console.log('formats:', singles.map(f => `${f}=${got[f]?.format ?? '✗'}`).join(' · '))
assert(singles.every(f => got[f]?.source?.origin === 'human' && got[f].source.file?.startsWith('inputs/')), 'every file stored in inputs/ and marked as provided')

const docx = await text(id, got['note.docx'].source.id)
const viaMd = /MarkItDown/.test(got['note.docx'].format)
assert(docx.includes('Seuil du code de surface') && docx.includes('lien visible') && !docx.includes('HYPERLINK'), `docx text (${viaMd ? 'MarkItDown' : 'intégré'})`)
assert(/\|\s*distance\s*\|\s*taux\s*\|/.test(docx) && docx.includes('0,3 & plus'), 'docx table rendered as markdown')
if (!viaMd) assert(/^# Seuil du code de surface/m.test(docx), 'docx heading → markdown heading')
assert(got['note.docx'].source.title === 'Note interne sur les codes' && got['note.docx'].source.authors?.[0] === 'Alice Martin', `docx metadata (${got['note.docx'].source.title})`)
const pptx = await text(id, got['slides.pptx'].source.id)
assert(got['slides.pptx'].source.pages === 3 && /Résultats clés/.test(pptx) && pptx.indexOf('Introduction') < pptx.indexOf('Conclusion'), `pptx: 3 slides in order (${got['slides.pptx'].source.pages})`)
if (!/MarkItDown/.test(got['slides.pptx'].format)) assert(pptx.includes('Dire que le seuil est robuste'), 'pptx speaker notes kept')
const xlsx = await text(id, got['mesures.xlsx'].source.id)
assert(got['mesures.xlsx'].source.kind === 'dataset' && xlsx.includes('erreur logique') && xlsx.includes('0.012') && xlsx.includes('Params'), `xlsx sheets (${got['mesures.xlsx'].source.pages ?? 1} page(s))`)
assert((await text(id, got['rapport.odt'].source.id)).includes('Titre ODT'), 'odt text')
const ep = await text(id, got['livre.epub'].source.id)
assert(ep.indexOf('Chapitre deux') >= 0 && ep.indexOf('Chapitre deux') < ep.indexOf('Chapitre un'), 'epub follows the spine order')
assert(got['notes.md'].source.title === 'Mes notes de départ', 'markdown title from first heading')
assert(got['data.csv'].source.kind === 'dataset', 'csv is a dataset')
assert((await text(id, got['page.html'].source.id)).includes('Contenu principal'), 'html converted')
assert((await text(id, got['calc.ipynb'].source.id)).includes('print(1+1)'), 'notebook converted')
assert((await text(id, got['latin1.txt'].source.id)).includes('Résumé élégant'), 'cp1252 text decoded')
assert(got['figure.png'].source.status === 'metadata' && /python|image/i.test(got['figure.png'].source.notes ?? ''), 'image kept with a usable note')
assert(got['article.pdf'].source.pages === 2 && (await text(id, got['article.pdf'].source.id)).includes('Page two'), 'pdf extracted page by page')
const pdf = await fetch(`${API}/projects/${id}/sources/${got['article.pdf'].source.id}/pdf`)
assert(pdf.ok && pdf.headers.get('content-type') === 'application/pdf', 'provided PDF viewable from inputs/')
const raw = await fetch(`${API}/projects/${id}/files/raw?path=${encodeURIComponent('inputs/data.csv')}`)
assert(raw.ok && (await raw.text()).startsWith('d,p,pl'), 'original reachable for bash/python (inputs/data.csv)')

const multi = await upload(id, ['dossier/a.tex', 'dossier/sous-dossier/b.py', 'notes.md'])
assert(multi.body.documents?.length === 3 && multi.body.documents[2].duplicate === true, 'several files per request, duplicate content detected')
const empty = await upload(id, ['vide.txt'])
assert(empty.status === 400 && /vide/i.test(empty.body.error), 'empty file refused')

const provided = (await call<any[]>('GET', `/projects/${id}/sources`)).filter(s => s.origin === 'human')
const expected = singles.length + 2
assert(provided.length === expected, `${provided.length}/${expected} provided documents in the library`)

// run: the lead sees the documents, then is told about one added mid-run
await call('POST', `/projects/${id}/start`)
const t0 = Date.now()
let added = false
let snap: any
while (Date.now() - t0 < 90_000) {
  await wait(600)
  snap = await call('GET', `/projects/${id}`)
  if (!added && snap.toolRuns.some((r: any) => r.tool === 'bash' && r.status === 'running')) {
    const r = await upload(id, ['mesures.xlsx'])
    // same content again: dedup → nothing announced; send a genuinely new file instead
    fs.writeFileSync(path.join(SAMPLES, 'late.md'), `# Ajout tardif\n\nNote ajoutée pendant la recherche ${Date.now()}.\n`)
    const late = await upload(id, ['late.md'])
    added = r.body.documents?.[0]?.duplicate === true && late.status === 200
  }
  if (['finished', 'error', 'paused'].includes(snap.project.status)) break
}
const lead = snap.messages.filter((m: any) => m.role === 'assistant').map((m: any) => String(m.content))
const first = snap.messages.find((m: any) => m.role === 'user')
assert(snap.project.status === 'finished', `run finished (${snap.project.status})`)
assert(String(first?.content ?? '').includes(`a joint ${expected} document`), 'start message points the lead to the documents')
assert(lead[0]?.includes(`DOCS_SEEN=${expected}`), `documents listed in the lead prompt (${lead[0]?.match(/DOCS_SEEN=\d+/)?.[0]})`)
assert(added && lead.at(-1)?.includes('ANNOUNCED=true'), 'document added mid-run announced to the lead (batched)')
assert(lead.at(-1)?.includes(`DOCS_SEEN=${expected + 1}`), 'late document visible in the prompt')
assert(snap.toolRuns.some((r: any) => r.tool === 'source_list' && r.status === 'ok' && /📎/.test(r.result ?? '')), 'source_list(origin=human) lists provided documents')

// deletion removes the original
const victim = provided.find(s => s.file === 'inputs/data.csv')
await call('DELETE', `/projects/${id}/sources/${victim.id}`)
const gone = await fetch(`${API}/projects/${id}/files/raw?path=${encodeURIComponent('inputs/data.csv')}`)
assert(gone.status === 404, 'deleting a provided document removes its original')
